INSERT INTO `products` (`id`, `title`, `slug`, `description`, `details`, `category_id`, `price`, `compare_at`, `tags`, `is_active`, `is_featured`, `created_at`, `updated_at`) VALUES (1,'Core Heavyweight Tee','core-heavyweight-tee','<p>220gsm combed cotton with a relaxed body and a ribbed collar that keeps its shape wash after wash.</p>','<p>Wash cold, inside out. Dry in the shade.</p>',1,99000,NULL,'new',1,1,'2026-09-26 13:11:51','2026-09-26 13:11:51');
INSERT INTO `products` (`id`, `title`, `slug`, `description`, `details`, `category_id`, `price`, `compare_at`, `tags`, `is_active`, `is_featured`, `created_at`, `updated_at`) VALUES (2,'Signature Oversized Tee','signature-oversized-tee','<p>Boxy, drop-shoulder fit in 240gsm cotton jersey. Made to be worn loose.</p>','<p>Wash cold, inside out. Dry in the shade.</p>',1,119000,NULL,'',1,1,'2026-09-26 12:11:51','2026-09-26 13:11:51');
INSERT INTO `products` (`id`, `title`, `slug`, `description`, `details`, `category_id`, `price`, `compare_at`, `tags`, `is_active`, `is_featured`, `created_at`, `updated_at`) VALUES (3,'Motion Cargo Pants','motion-cargo-pants','<p>Twill cargo pants with a tapered leg, six pockets and a soft brushed waistband.</p>','<p>Wash cold, inside out. Dry in the shade.</p>',2,245000,NULL,'new',1,1,'2026-09-26 11:11:51','2026-09-26 13:11:51');
INSERT INTO `products` (`id`, `title`, `slug`, `description`, `details`, `category_id`, `price`, `compare_at`, `tags`, `is_active`, `is_featured`, `created_at`, `updated_at`) VALUES (4,'Everyday Chino Pants','everyday-chino-pants','<p>Stretch cotton chinos with a clean straight cut for office days and weekends.</p>','<p>Wash cold, inside out. Dry in the shade.</p>',2,219000,259000,'',1,1,'2026-09-26 10:11:51','2026-09-26 13:11:51');
INSERT INTO `products` (`id`, `title`, `slug`, `description`, `details`, `category_id`, `price`, `compare_at`, `tags`, `is_active`, `is_featured`, `created_at`, `updated_at`) VALUES (5,'Eid Cotton Punjabi','eid-cotton-punjabi','<p>Fine cotton punjabi with tonal embroidery along the placket and concealed side pockets.</p>','<p>Wash cold, inside out. Dry in the shade.</p>',3,349000,NULL,'new',1,0,'2026-09-26 09:11:51','2026-09-26 13:11:51');
INSERT INTO `products` (`id`, `title`, `slug`, `description`, `details`, `category_id`, `price`, `compare_at`, `tags`, `is_active`, `is_featured`, `created_at`, `updated_at`) VALUES (6,'Embroidered Linen Punjabi','embroidered-linen-punjabi','<p>Linen-blend punjabi with gold thread embroidery and a mandarin collar. Breathable for long festive days.</p>','<p>Wash cold, inside out. Dry in the shade.</p>',3,429000,499000,'',1,0,'2026-09-26 08:11:51','2026-09-26 13:11:51');
INSERT INTO `products` (`id`, `title`, `slug`, `description`, `details`, `category_id`, `price`, `compare_at`, `tags`, `is_active`, `is_featured`, `created_at`, `updated_at`) VALUES (7,'Short Linen Kurta','short-linen-kurta','<p>Hip-length kurta in washed linen with side slits. Pairs with chinos or jeans.</p>','<p>Wash cold, inside out. Dry in the shade.</p>',4,229000,NULL,'',1,0,'2026-09-26 07:11:51','2026-09-26 13:11:51');
